def pieces_of(rows):
    P = []
    for i, row in enumerate(rows):
        j = 0
        while j < len(row) - 1:
            if row[j].isalpha() and row[j + 1] == row[j]:
                P.append((i, j, row[j]))
                j += 2
            else:
                j += 1
    return P


def wid(r, T, n):
    w = [3] * n
    for _ in range(T - 3 * n):
        w[r.randrange(n)] += 1
    return w


def bnds(w):
    b = []
    t = 0
    for v in w[:-1]:
        t += v
        b.append(t)
    return b


def look(b, n, P, x, H):
    """True count k for topping x, plus every rival reading of the same picture."""
    A = [0] * n
    Lf = [0] * n
    Wh = [0] * n
    pc = [0] * n
    rc = [[0] * n for _ in range(H)]
    lc = [{} for _ in range(n)]
    sx = so = 0
    for row, c, L in P:
        s1 = bisect.bisect_right(b, c)
        s2 = bisect.bisect_right(b, c + 1)
        st = s2 != s1
        for s in ((s1, s2) if st else (s1,)):
            pc[s] += 1
            lc[s][L] = lc[s].get(L, 0) + 1
            if L == x:
                A[s] += 1
                rc[row][s] += 1
        if L == x:
            Lf[s1] += 1
            if st:
                sx += 1
            else:
                Wh[s1] += 1
        elif st:
            so += 1
    k = sum(1 for v in A if v >= 2)
    riv = (sum(1 for v in Lf if v >= 2), sum(1 for v in Wh if v >= 2),
           sum(1 for v in A if v >= 1), sum(1 for v in A if v == 2),
           sum(1 for v in A if v >= 3),
           sum(1 for d in lc if any(t >= 2 for t in d.values())),
           sum(1 for p in P if p[2] == x), sx, so, sx + so, n, n - 1,
           sum(v * (v - 1) // 2 for v in A), sum(v for v in A if v >= 2),
           sum(1 for s in range(n) if any(rc[i][s] >= 2 for i in range(H))),
           sum(1 for v in A if v == 0), sum(1 for v in pc if v >= 2),
           sum(1 for v in pc if v >= 3), sum(1 for v in pc if v == 1))
    return min(pc) > 0, k, riv, sx, so, sum(1 for v in A if v == 1)


def grade(b, n, P, xy, kk, H):
    """0 = falsifies every rival for both toppings, 1 = the essential ones, 2 = counts only, 3 = no."""
    best = 0
    for x, k in zip(xy, kk):
        v, k2, riv, sx, so, one = look(b, n, P, x, H)
        if not v or k2 != k:
            return 3
        R = riv[:3] + riv[4:12] + riv[13:]
        if sx < 1 or so < 1 or one < 1 or any(u == k for u in riv[:2]):
            best = max(best, 2)
        elif any(u == k for u in R) or any(u in kk for u in riv[8:12] + riv[5:6]):
            best = max(best, 1)
    return best


def render(rows, b):
    out = []
    for row in rows:
        s = ""
        for i, ch in enumerate(row):
            if i in b:
                s += "|"
            s += ch
        out.append(s)
    return out


def chk(clue, s):
    """Exactly the scorer, so solve never ships anything the scorer would reject."""
    a = clue.split("\n")
    C = [l for l in a[1:] if "." in l]
    R = [l.rstrip() for l in s.split("\n") if "." in l]
    if [l.replace("|", "") for l in R] != C:
        return 0
    S = [l.split("|") for l in R]
    W = [len(g) for g in S[0]]
    n = len(W)
    return int(3 < n < 9 and min(W) > 2 and all([len(g) for g in p] == W for p in S)
               and all(any(h.isalpha() for p in S for h in p[i]) for i in range(n))
               and all(sum(sum(len(re.findall(u[0] + "+", p[i])) for p in S) > 1
                           for i in range(n)) == int(u[1])
                       for u in (a[0][:2], a[0][2:4])))


def fast(b, n, P, xy, kk):
    """Cheap gate: both counts right and no slice left without a topping."""
    A = [0] * n
    B = [0] * n
    pc = [0] * n
    for row, c, L in P:
        s1 = bisect.bisect_right(b, c)
        s2 = bisect.bisect_right(b, c + 1)
        for s in ((s1, s2) if s2 != s1 else (s1,)):
            pc[s] += 1
            if L == xy[0]:
                A[s] += 1
            elif L == xy[1]:
                B[s] += 1
    return (min(pc) > 0 and sum(1 for v in A if v >= 2) == kk[0]
            and sum(1 for v in B if v >= 2) == kk[1])


def solve(clue):
    a = clue.split("\n")
    xy = (a[0][0], a[0][2])
    kk = (int(a[0][1]), int(a[0][3]))
    rows = [l for l in a[1:] if "." in l]
    P = pieces_of(rows)
    H = len(rows)
    T = len(rows[0])
    r = random.Random(clue)
    crust = "#" * T
    hold = None
    for it in range(14000):
        n = r.randint(4, 8)
        if 3 * n > T:
            continue
        b = bnds(wid(r, T, n))
        if not fast(b, n, P, xy, kk):
            continue
        g = grade(b, n, P, xy, kk, H)
        s = "\n".join(render([crust] + rows + [crust], set(b)))
        if not chk(clue, s):
            continue
        if g == 0:
            return s
        if hold is None or g < hold[0]:
            hold = (g, s)
    return hold[1] if hold else ""

